fun P odd even one =>
  WellFounded.Nat.fix (fun x => x.val) fun p a =>
    if h : p.val = 1 then ⋯ ▸ one
    else
      have hp := ⋯;
      let q := ⟨p.val / 2, ⋯⟩;
      if he : p.val % 2 = 0 then ⋯ ▸ even q (a q ⋯) else ⋯ ▸ odd q (a q ⋯)

fun d =>
  have x := NativeBridge.Incremental.DecimalRepresentation.trimHead d.reverse;
  (x.fst.reverse, x.snd)

fun d =>
  have x := NativeBridge.Incremental.DecimalRepresentation.trimTail d.snd;
  ((d.fst, x.fst), x.snd)

fun d =>
  have x := NativeBridge.Incremental.HexadecimalRepresentation.trimHead d.reverse;
