fun d =>
  have x := NativeBridge.Incremental.HexadecimalRepresentation.trimTail d.snd;
  ((d.fst, x.fst), x.snd)

fun b =>
  have v := { toFin := b };
  (v.getLsbD 0, v.getLsbD 1, v.getLsbD 2, v.getLsbD 3, v.getLsbD 4, v.getLsbD 5, v.getLsbD 6, v.getLsbD 7)

fun x y =>
  have z := BitVec.ofNat 63 (BitVec.toNat x + BitVec.toNat y + 1);
  if BitVec.toNat x + BitVec.toNat y + 1 < 2 ^ 63 then (false, z) else (true, z)

fun hi lo y =>
  if BitVec.toNat hi < BitVec.toNat y then
    have n := BitVec.toNat hi * 2 ^ 63 + BitVec.toNat lo;
    (BitVec.ofNat 63 (n / BitVec.toNat y), BitVec.ofNat 63 (n % BitVec.toNat y))
  else (0, 0)
